CREATE TABLE EMPLOYEE (
  Salary DECIMAL(10,2),
  SupervisorSalary DECIMAL(10,2),
  CHECK (Salary <= SupervisorSalary)
);

SELECT Fname, Lname, Address
FROM EMPLOYEE
WHERE Dno = 5;

SELECT E.Fname, E.Lname, D.Dname
FROM EMPLOYEE AS E, DEPARTMENT AS D
WHERE E.Dno = D.Dnumber;

UPDATE STUDENT
SET CGPA = 8.9
WHERE USN = '1VV23CS001';
